/// `textOf` over the binary wire.
#[napi(js_name = "textOfWire")]
pub fn text_of_wire() -> napi::Result<f64> {
    wire_io(|r, w| {
        let max: f64 = r.f64()?;
        let description: Option<String> = r.opt_js(|r| r.string16())?;
        let out = &port::text_of(max, description)?;
        wire::write_value(w, out, &S_TEXT_OF_OUT)?;
        Ok(())
    })
}

