/// `closed` over the binary wire.
#[napi(js_name = "closedWire")]
pub fn closed_wire() -> napi::Result<f64> {
    wire_io(|r, w| {
        let properties: Value = wire::read_value(r, &S_CLOSED_0)?;
        let required: Value = wire::read_value(r, &S_CLOSED_1)?;
        let out = &port::closed(properties, required)?;
        wire::write_value(w, out, &S_CLOSED_OUT)?;
        Ok(())
    })
}

