/// `pluginPath` over the binary wire.
#[napi(js_name = "pluginPathWire")]
pub fn plugin_path_wire() -> napi::Result<f64> {
    wire_io(|r, w| {
        let description: Option<String> = r.opt_js(|r| r.string16())?;
        let out = &port::plugin_path(description)?;
        wire::write_value(w, out, &S_PLUGIN_PATH_OUT)?;
        Ok(())
    })
}

