/// `rowSchema` over the binary wire.
#[napi(js_name = "rowSchemaWire")]
pub fn row_schema_wire() -> napi::Result<f64> {
    wire_io(|r, w| {
        let types: Vec<String> = r.list(|r| r.string16())?;
        let out = &port::row_schema(types)?;
        wire::write_value(w, out, &S_ROW_SCHEMA_OUT)?;
        Ok(())
    })
}
